INSERT INTO expected_quiz_hint
    (step_order, slot_order, quiz_type, difficulty, question_text, replacement_question_text, hint)
VALUES
    (0, 1, 'OX', 'EASY', 'TCP는 연결 지향 프로토콜이다.', NULL, '통신 시작 전에 연결 설정 절차를 거치는지, 손실 복구와 순서 보장을 위해 상태를 유지하는지 떠올려 보세요.'),
    (0, 2, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 코드의 시간복잡도는?', NULL, '각 반복문의 실행 횟수를 따로 센 뒤, 중첩된 반복문의 전체 연산 수는 두 횟수를 곱해 계산하세요.'),
    (0, 3, 'KEYWORD_BLANK', 'HARD', '스택은 ___ 방식으로 데이터를 관리하는 자료구조다.', NULL, '한쪽 끝에서만 삽입과 삭제가 일어나며 가장 최근에 들어온 항목이 먼저 나오는 순서를 떠올려 보세요.'),
    (1, 1, 'OX', 'EASY', '운영체제의 커널은 사용자 프로그램과 완전히 분리된 특권 수준에서 실행되며, 하드웨어 자원 관리의 핵심 역할을 담당한다.', NULL, 'CPU 특권 명령과 메모리·장치 관리를 일반 응용 코드가 직접 수행하도록 허용할 때의 보호 문제를 생각해 보세요.'),
    (1, 2, 'OX', 'EASY', '인터럽트는 항상 소프트웨어가 명시적으로 발생시키는 사건만을 의미하며, 하드웨어 장치는 인터럽트를 발생시킬 수 없다.', NULL, '키보드 입력이나 디스크 작업 완료처럼 장치가 CPU의 주의를 요청하는 상황도 함께 떠올려 보세요.'),
    (1, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 시스템 콜에 대한 설명으로 가장 알맞은 것은 무엇인가?', NULL, '사용자 모드 코드가 파일·프로세스 같은 보호된 서비스를 이용할 때 어떤 경계를 통과하는지 살펴보세요.'),
    (1, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 코드와 관련해 가장 알맞은 설명을 고르시오.', NULL, '파일 입출력 코드가 사용자 모드 함수 호출만으로 끝나는지, 보호된 자원 접근을 누가 중재하는지 구분하세요.'),
    (1, 5, 'KEYWORD_BLANK', 'HARD', '응용 프로그램이 운영체제의 보호된 기능을 사용하기 위해 요청하는 표준 인터페이스를 ___이라고 한다.', NULL, '응용 프로그램이 파일 열기나 프로세스 생성처럼 보호된 기능을 커널에 요청할 때 거치는 공식 경계를 가리킵니다.'),
    (2, 1, 'OX', 'EASY', 'PCB는 운영체제가 각 프로세스의 상태와 관리 정보를 저장하기 위해 사용하는 자료구조이다.', NULL, '프로세스가 중단되었다가 다시 실행되려면 상태·레지스터·스케줄링 정보를 어디엔가 보존해야 함을 생각해 보세요.'),
    (2, 2, 'OX', 'EASY', '프로세스가 Running 상태에 있으면 반드시 CPU를 사용 중이며, I/O 완료를 기다리는 상태일 수는 없다.', NULL, '프로세스 상태 모델에서 CPU 점유 상태와 입출력 완료를 기다리는 상태는 서로 다른 이름과 전이 조건을 가집니다.'),
    (2, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 프로세스가 Waiting 상태에서 Ready 상태로 전이되는 가장 적절한 경우는 무엇인가?', NULL, '대기 원인이 해소된 프로세스는 즉시 CPU를 점유하는지, 먼저 실행 가능한 큐로 이동하는지 구분하세요.'),
    (2, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '단일 CPU 환경에서 CPU를 사용 중인 프로세스 P에 타이머 인터럽트가 발생했다. P는 종료되거나 입출력을 요청하지 않았으며, 운영체제는 P의 실행 정보를 저장한 뒤 다른 프로세스에 CPU를 넘겼다. 이때 P의 상태 전이로 가장 알맞은 것을 고르시오.', NULL, '상태 전이는 인터럽트 직전 P의 상태와 CPU를 넘긴 뒤 P가 기다리는 사건이 있는지를 각각 확인해 판단해 보세요.'),
    (2, 5, 'KEYWORD_BLANK', 'HARD', '운영체제가 실행 중인 프로세스의 레지스터 값과 프로그램 카운터 등을 저장해 두었다가, 다른 프로세스로 CPU를 넘긴 뒤 다시 복원하는 작업을 ___이라고 한다.', NULL, 'CPU를 넘기기 전 현재 실행 흐름의 레지스터와 위치를 저장하고 다음 흐름의 정보를 복원하는 절차입니다.'),
    (3, 1, 'OX', 'EASY', '스레드는 같은 프로세스 안에서 코드, 데이터, 힙 메모리를 공유할 수 있다.', NULL, '같은 프로세스에 속한 실행 흐름들은 주소 공간의 큰 부분을 함께 쓰되 각자 스택과 레지스터를 가집니다.'),
    (3, 2, 'OX', 'EASY', '멀티스레딩을 사용하면 항상 프로그램의 실행 속도가 빨라진다.', NULL, '병렬화 이점뿐 아니라 스레드 생성, 동기화, 문맥 교환 비용과 순차 구간의 비율도 함께 고려하세요.'),
    (3, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 스레드 동기화가 필요한 상황으로 가장 적절한 것은 무엇인가?', NULL, '동시에 읽고 쓰는 공유 가변 데이터가 있는지 여부를 기준으로 각 상황을 구분하세요.'),
    (3, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 코드에 대한 설명으로 가장 알맞은 것은 무엇인가?', NULL, '증가 연산은 읽기·계산·쓰기의 여러 단계로 나뉠 수 있어 두 실행 흐름의 단계가 겹칠 때 결과를 추적하세요.'),
    (3, 5, 'KEYWORD_BLANK', 'HARD', '여러 스레드가 서로 상대가 가진 락이 해제되기만 기다리며 영원히 진행하지 못하는 상태를 ___라고 한다.', NULL, '여러 실행 흐름이 자원을 하나씩 점유한 채 서로의 자원이 풀리기만 기다려 누구도 진행하지 못하는 상황입니다.'),
    (4, 1, 'OX', 'EASY', 'FCFS 스케줄링은 먼저 도착한 프로세스가 먼저 CPU를 할당받는 방식이다.', NULL, '두 프로세스의 도착 시각이 다를 때 준비 큐의 삽입·선택 순서를 직접 그려 보고, 실행 중 작업의 선점 여부도 함께 확인해 보세요.'),
    (4, 2, 'OX', 'EASY', '라운드로빈 스케줄링에서 타임 퀀텀이 매우 커지면 동작 특성이 FCFS와 비슷해질 수 있다.', NULL, 'CPU를 넘기는 시간 간격이 각 작업의 실행 시간보다 훨씬 길어지면 실제 선점이 얼마나 자주 일어나는지 생각하세요.'),
    (4, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 SJF 스케줄링의 특징으로 가장 알맞은 것은 무엇인가?', NULL, '스케줄러가 비교하는 기준이 도착 시각, 시간 조각, 우선순위 값, 예상 CPU 사용 시간 중 무엇인지 구분하세요.'),
    (4, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '세 프로세스 P1(우선순위 3), P2(우선순위 1), P3(우선순위 2)가 모두 같은 시각에 준비 상태가 된다. 숫자가 작을수록 우선순위가 높으며, 비선점형 우선순위 스케줄링을 사용한다. 이 상황에 대한 설명으로 옳은 것을 고르시오.', NULL, '숫자가 작을수록 우선순위가 높다는 조건을 세 값에 먼저 적용하고, 비선점 여부는 첫 선택 이후에 고려하세요.'),
    (4, 5, 'KEYWORD_BLANK', 'HARD', '라운드로빈 스케줄링에서 ___이(가) 너무 작으면 응답성은 좋아질 수 있지만 문맥 교환 오버헤드가 커질 수 있다.', NULL, '각 프로세스가 한 차례에 CPU를 사용할 수 있도록 정해 둔 시간 단위로, 지나치게 짧으면 교대 비용이 늘어납니다.'),
    (5, 1, 'OX', 'EASY', '선점형 CPU 스케줄링에서는 실행 중인 프로세스가 타이머 인터럽트나 더 높은 우선순위 프로세스의 도착으로 CPU를 빼앗길 수 있다.', NULL, '실행 중인 작업보다 긴급한 작업이 도착하거나 시간 할당량이 끝날 때 스케줄러가 개입할 수 있는 방식을 떠올리세요.'),
    (5, 2, 'OX', 'EASY', '비선점형 스케줄링에서는 실행 중인 프로세스가 I/O 요청이나 종료를 하기 전에도 운영체제가 언제든지 CPU를 강제로 회수할 수 있다.', NULL, '이 방식에서는 실행 흐름이 자발적으로 CPU를 놓는 종료·대기 전이까지 스케줄러가 기다리는 것이 핵심입니다.'),
    (5, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '멀티레벨 큐 스케줄링에 대한 설명으로 가장 알맞은 것은 무엇인가?', NULL, '멀티레벨 큐와 멀티레벨 피드백 큐를 구분할 때 프로세스의 큐 이동 가능 여부와 큐별 정책 설정 여부를 나눠 확인하세요.'),
    (5, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '프로세스 A(우선순위 3, 버스트 시간 5), B(우선순위 1, 버스트 시간 8), C(우선순위 2, 버스트 시간 2), D(우선순위 4, 버스트 시간 1)가 모두 시각 0에 준비 큐에 있다. 숫자가 작을수록 우선순위가 높은 선점형 우선순위 스케줄링을 사용할 때, 가장 먼저 CPU를 할당받는 프로세스로 알맞은 것을 고르시오.', NULL, '버스트 길이보다 우선순위 숫자의 대소가 먼저 적용되며, 주어진 규칙에서 가장 작은 값을 찾으세요.'),
    (5, 5, 'KEYWORD_BLANK', 'HARD', '우선순위 기반 스케줄링에서 낮은 우선순위 프로세스가 오랫동안 CPU를 받지 못하는 현상을 ___라고 하며, 이를 완화하기 위해 기다린 시간에 따라 우선순위를 점차 높이는 기법을 ___이라고 한다.', NULL, '낮은 우선순위 작업이 계속 밀리는 문제와, 대기 시간이 길수록 우선순위를 단계적으로 올리는 완화 기법을 함께 떠올리세요.'),
    (6, 1, 'OX', 'EASY', '임계구역은 여러 프로세스나 스레드가 동시에 접근해도 항상 안전하도록 별도 보호가 필요 없는 코드 구간이다.', NULL, '공유 데이터를 읽고 쓰는 구간에 여러 실행 흐름이 겹쳐 들어갈 때 연산 순서에 따라 값이 달라질 수 있음을 생각하세요.'),
    (6, 2, 'OX', 'EASY', '뮤텍스는 보통 잠금을 획득한 실행 흐름이 나중에 그 잠금을 해제하는 방식으로 사용된다.', NULL, '소유권이 있는 잠금은 획득 주체와 해제 주체의 관계를 추적하며 사용하는 것이 일반적입니다.'),
    (6, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 세마포어에 대한 설명으로 가장 알맞은 것은 무엇인가?', NULL, '각 선택지가 소유권을 요구하는지, 단일 진입만 허용하는지, 여러 동일 자원의 가용 개수까지 표현할 수 있는지를 비교해 보세요.'),
    (6, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 코드에 대한 설명으로 가장 알맞은 것은 무엇인가?', NULL, '초깃값이 하나일 때 대기 연산 후 동시에 임계구역에 들어갈 수 있는 실행 흐름 수를 계산하세요.'),
    (6, 5, 'KEYWORD_BLANK', 'HARD', '공유 자원에 대해 한 시점에 하나의 실행 흐름만 임계구역에 들어가도록 보장하는 성질을 ___라고 한다.', NULL, '공유 구간에 동시에 진입할 수 있는 실행 흐름을 하나로 제한해 경쟁을 막는 성질입니다.'),
    (7, 1, 'OX', 'EASY', '생산자-소비자 문제에서 공유 버퍼에 접근할 때, 여러 스레드가 동시에 버퍼 상태를 변경해도 항상 올바른 결과가 보장된다.', NULL, '버퍼의 빈칸 수와 항목 수를 여러 실행 흐름이 동시에 갱신할 때 연산이 겹치는 경우를 추적하세요.'),
    (7, 2, 'OX', 'EASY', '모니터는 공유 자원에 대한 상호 배제를 구조적으로 지원하며, 조건이 만족되지 않으면 조건 변수를 통해 스레드를 기다리게 할 수 있다.', NULL, '공유 데이터 접근을 한곳에 묶고, 조건이 충족될 때까지 실행 흐름을 재웠다가 깨우는 추상화를 떠올리세요.'),
    (7, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '세마포어를 사용한 생산자-소비자 문제에서 일반적으로 empty 세마포어의 의미로 가장 알맞은 것은 무엇인가?', NULL, '생산자가 항목을 넣기 전과 소비자가 항목을 꺼낸 후에 empty 값이 어떻게 변하는지 작은 버퍼 예제로 추적해 보세요.'),
    (7, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 코드에서 발생할 수 있는 가장 적절한 문제를 고르시오.', NULL, '각 증가를 읽기·더하기·쓰기 단계로 나누고 두 스레드의 가능한 실행 순서를 바꿔 가며 최종값을 비교해 보세요.'),
    (7, 5, 'KEYWORD_BLANK', 'HARD', '모니터에서 어떤 조건이 만족될 때까지 스레드를 잠들게 하고, 이후 다른 스레드가 그 조건 변화에 맞춰 깨울 수 있게 하는 동기화 도구는 ___이다.', NULL, '공유 상태가 특정 조건을 만족할 때까지 실행 흐름을 재우고, 상태 변경 시 깨우는 모니터 내부 도구입니다.'),
    (8, 1, 'OX', 'EASY', '교착상태의 4대 필요 조건 중 하나라도 성립하지 않으면 교착상태는 발생할 수 없다.', NULL, '네 조건 각각이 필요 조건인지 충분 조건인지 구분한 뒤, 논리곱에서 하나가 성립하지 않는 경우를 대입해 보세요.'),
    (8, 2, 'OX', 'EASY', '교착상태 회피는 시스템이 이미 교착상태에 빠진 뒤 이를 탐지하고 복구하는 기법이다.', NULL, '자원 요청을 승인하기 전에 승인 후에도 모든 프로세스를 끝낼 수 있는 순서가 남는지 검사하는 접근과 발생 후 탐지를 구분하세요.'),
    (8, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 교착상태 예방(prevention)을 위해 순환 대기 조건을 직접 깨는 방법으로 가장 적절한 것은 무엇인가?', NULL, '각 보기의 조치가 상호 배제·점유 대기·비선점·순환 대기 중 어느 조건을 겨냥하는지 하나씩 대응해 보세요.'),
    (8, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 코드 상황에 대한 설명으로 가장 적절한 것은 무엇인가?', NULL, '두 스레드별로 첫 번째 락 획득 후 두 번째 락을 요청하는 시점의 보유·대기 관계를 표로 그려 보세요.'),
    (8, 5, 'KEYWORD_BLANK', 'HARD', '은행원 알고리즘에서 현재 자원 할당 상태가 모든 프로세스가 어떤 순서로든 완료될 수 있는 상태라면 이를 ___라고 한다.', NULL, '현재 가용 자원과 각 프로세스의 남은 최대 요구량을 대입해, 모든 프로세스를 끝낼 수 있는 순서가 하나 이상 존재하는지 확인해 보세요.'),
    (9, 1, 'OX', 'EASY', '외부 단편화는 연속 할당 방식에서 빈 메모리 공간이 여러 조각으로 흩어져, 총합은 충분해도 큰 프로세스를 배치하지 못하는 현상을 말한다.', NULL, '빈 공간의 총량과 한 덩어리로 연속된 최대 공간은 다를 수 있으므로 큰 요청을 배치할 수 있는지 구분하세요.'),
    (9, 2, 'OX', 'EASY', '페이징에서는 프로세스의 논리 주소 공간과 물리 메모리 공간을 같은 크기의 단위로 나누어 관리하므로 외부 단편화를 줄일 수 있다.', NULL, '논리 공간과 물리 공간을 고정 크기 조각으로 나누면 프로세스 전체를 한곳에 연속 배치할 필요가 있는지 생각하세요.'),
    (9, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 세그멘테이션에 대한 설명으로 가장 옳은 것은 무엇인가?', NULL, '주소 공간의 분할 경계가 일정한 바이트 수를 따르는지, 프로그램의 논리적 구성에 따라 달라지는지를 기준으로 보기를 비교하세요.'),
    (9, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 코드 지문을 보고 가장 옳은 설명을 고르시오.', NULL, '주소를 고정 크기 단위로 나눌 때 몫과 나머지가 각각 무엇을 나타내는지 확인하세요.'),
    (9, 5, 'KEYWORD_BLANK', 'HARD', '연속 할당에서 빈 공간이 여러 조각으로 흩어져 큰 프로세스를 배치하지 못하는 현상을 ___라고 하며, 이를 줄이기 위해 메모리의 사용 중인 블록들을 한쪽으로 모아 큰 연속 공간을 만드는 작업을 ___이라고 한다.', NULL, '흩어진 빈 공간 때문에 큰 연속 영역을 못 만드는 현상과, 사용 중인 블록을 한쪽으로 옮겨 빈 공간을 합치는 작업을 묻습니다.'),
    (10, 1, 'OX', 'EASY', '페이지 폴트는 프로세스가 접근한 페이지가 현재 물리 메모리에 없을 때 발생한다.', NULL, '주소 변환 중 페이지 테이블 엔트리가 현재 접근 가능한 물리 프레임을 가리키는지와, 가리키지 않을 때 운영체제가 어떤 처리를 시작하는지 살펴보세요.'),
    (10, 2, 'OX', 'EASY', 'LRU 페이지 교체 알고리즘은 앞으로 가장 오랫동안 사용되지 않을 페이지를 정확히 예측하여 교체한다.', NULL, '이 알고리즘은 미래를 예측하는 대신 과거의 접근 기록을 근거로 교체 대상을 고릅니다.'),
    (10, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 FIFO 페이지 교체 알고리즘의 특징으로 가장 알맞은 것은 무엇인가?', NULL, '각 페이지에 기록해야 할 정보가 최근 접근 시점인지, 적재 시점인지, 사용 횟수인지 구분해 보세요.'),
    (10, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '페이지 프레임이 3개이고 페이지 참조열이 [1, 2, 3, 2, 4] 순서로 주어졌을 때, LRU 알고리즘의 설명으로 가장 알맞은 것을 고르시오. 각 숫자는 페이지 번호를 의미한다.', NULL, '참조열을 따라 마지막 사용 시점을 갱신한 뒤 새 페이지가 들어올 때 가장 오래 손대지 않은 항목을 찾으세요.'),
    (10, 5, 'KEYWORD_BLANK', 'HARD', '프로세스들이 동시에 과도한 페이지 폴트를 일으켜 CPU 이용률이 떨어지고, 운영체제가 더 많은 다중 프로그래밍을 허용하려 하면서 상황이 악화되는 현상을 ___이라고 한다.', NULL, '페이지 부재 처리에 대부분의 시간을 써 실제 명령 실행이 줄고, 작업 수를 늘릴수록 더 악화되는 현상입니다.'),
    (11, 1, 'OX', 'EASY', '연속 할당(contiguous allocation)은 하나의 파일을 디스크 상에서 연속된 블록들에 저장하는 방식이다.', NULL, '파일 블록의 시작 위치와 길이만으로 전체 위치를 계산할 수 있는 배치 방식의 특징을 떠올리세요.'),
    (11, 2, 'OX', 'EASY', '트리 구조 디렉토리에서는 하나의 파일이 반드시 하나의 경로로만 접근 가능하므로, 같은 파일을 여러 디렉토리에서 공유할 수 없다.', '유닉스 계열의 계층형 이름 공간에서는 하나의 파일이 반드시 하나의 경로로만 접근 가능하므로, 같은 파일을 여러 디렉터리에서 공유할 수 없다.', '엄밀한 트리 모델과 링크를 허용한 유닉스 계열 이름 공간을 구분하고, 링크가 대상에 이르는 경로 수를 어떻게 바꾸는지 살펴보세요.'),
    (11, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 FAT(File Allocation Table) 방식의 특징으로 가장 알맞은 것은 무엇인가?', NULL, '파일 블록의 연결 정보를 데이터 블록 안에 둘 때와 별도 자료구조에 모을 때 다음 블록을 찾는 경로가 어떻게 달라지는지 비교해 보세요.'),
    (11, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 코드 지문이 설명하는 파일 할당 방식으로 가장 적절한 것은 무엇인가?', NULL, '코드가 다음 블록 포인터를 따라가는지, 시작 위치와 길이로 계산하는지, 주소 목록을 조회하는지 실행 순서대로 분류해 보세요.'),
    (11, 5, 'KEYWORD_BLANK', 'HARD', '유닉스 계열 파일 시스템에서 파일의 소유자, 권한, 크기, 데이터 블록 위치 같은 메타데이터를 저장하는 자료구조는 ___ 이다.', NULL, '유닉스 계열에서 파일 이름은 디렉터리에 두고, 권한·크기·소유자와 데이터 블록 포인터를 별도로 담는 구조입니다.'),
    (12, 1, 'OX', 'EASY', '버퍼링은 입출력 장치와 프로세스 사이의 속도 차이를 완화하기 위해 메모리의 중간 저장 공간을 사용하는 기법이다.', NULL, '장치와 프로세스의 처리 속도가 다를 때 데이터가 즉시 전달되는 경우와 잠시 머무는 경우의 흐름을 비교해 보세요.'),
    (12, 2, 'OX', 'EASY', '스풀링은 여러 작업의 출력을 디스크 등에 모아 두었다가 순서대로 처리하게 하므로, 프린터처럼 한 번에 하나의 작업만 처리하는 장치의 공유에 활용될 수 있다.', NULL, '프린터가 여러 요청을 동시에 처리할 수 없을 때 요청이 장치에 바로 전달되는지 별도 대기 단계가 있는지를 살펴보세요.'),
    (12, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 디스크 스케줄링 알고리즘 SSTF의 특징으로 가장 알맞은 것은 무엇인가?', NULL, '현재 헤드에서 각 요청까지 필요한 이동 거리를 먼저 계산한 뒤, 알고리즘 이름이 어떤 선택 기준을 암시하는지 연결해 보세요.'),
    (12, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 코드 상황에 대한 설명으로 가장 알맞은 것을 고르시오.', NULL, '인쇄 요청을 만든 프로세스와 실제 프린터가 작업을 소비하는 시점을 나누어, 둘 사이에 어떤 저장·대기 단계가 있는지 추적해 보세요.'),
    (12, 5, 'KEYWORD_BLANK', 'HARD', '디스크 스케줄링에서 헤드가 한 방향으로 이동하며 요청을 처리하다가 끝에 도달하면 방향을 바꾸어 다시 처리하는 방식은 ___ 알고리즘이다.', NULL, '헤드의 현재 진행 방향을 유지하며 경로상의 요청을 처리한 뒤, 경계에 이르면 이동 방향을 바꾸는 규칙을 떠올려 보세요.'),
    (13, 1, 'OX', 'EASY', '생성 패턴은 객체 생성 과정을 캡슐화하여, 어떤 구체 클래스의 인스턴스를 만들지 결정하는 책임을 분리하는 데 도움을 준다. 이 설명은 옳을까?', NULL, '객체를 만드는 구체 절차와 구현 클래스 선택을 사용하는 코드에서 분리할 때 변경 영향이 어떻게 달라지는지 생각하세요.'),
    (13, 2, 'OX', 'EASY', '싱글턴 패턴에서 정적 필드에 인스턴스를 저장해 두었다고 해서, 멀티스레드 환경에서도 항상 자동으로 스레드 안전성이 보장되는 것은 아니다. 이 설명은 옳을까?', NULL, '여러 스레드가 최초 접근 시점에 동시에 빈 필드를 확인하고 각각 인스턴스를 만들 수 있는 실행 순서를 그려 보세요.'),
    (13, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 생성 패턴에 해당하지 않는 것은 무엇인가?', NULL, '각 보기를 GoF의 생성·구조·행동 분류에 대응시키고, 객체를 만드는 책임을 주로 다루는지 확인해 보세요.'),
    (13, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 멀티스레드 환경에서 싱글턴의 지연 초기화 구현에 대해 가장 적절한 설명은 무엇인가?', NULL, '두 스레드가 null 검사와 대입을 번갈아 수행하는 가능한 순서를 적어, 생성 횟수가 한 번으로 제한되는지 확인해 보세요.'),
    (13, 5, 'KEYWORD_BLANK', 'HARD', '싱글턴의 지연 초기화에서 성능과 안전성을 함께 고려할 때 자주 언급되는 기법은 ___이며, 올바른 구현에서는 메모리 재배치와 가시성 문제를 함께 고려해야 한다.', NULL, '잠금 밖에서 한 번 확인하고 잠금 안에서 다시 확인해 불필요한 동기화를 줄이되 가시성까지 챙기는 기법입니다.'),
    (14, 1, 'OX', 'EASY', '팩토리 메서드 패턴은 객체 생성을 위한 인터페이스를 정의하고, 어떤 구체 클래스를 생성할지는 서브클래스가 결정하도록 위임하는 패턴이다.', NULL, '생성 메서드의 선언 위치와 실제 제품 타입을 선택하는 위치가 같은지 나뉘는지를 중심으로 구조를 살펴보세요.'),
    (14, 2, 'OX', 'EASY', '추상 팩토리 패턴은 서로 관련되거나 함께 사용되는 객체들의 집합을 생성하기 위한 인터페이스를 제공하며, 클라이언트는 개별 제품의 구체 클래스를 몰라도 된다.', NULL, '클라이언트가 구체 제품 클래스를 직접 아는지와 서로 호환되는 객체들을 함께 교체할 수 있는지를 기준으로 구조를 살펴보세요.'),
    (14, 3, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 중 팩토리 메서드와 추상 팩토리의 차이를 가장 정확히 설명한 것은 무엇인가?', NULL, '두 패턴을 생성 결정의 확장 수단이 상속인지 객체 합성인지, 다루는 제품 범위가 하나인지 묶음인지 두 축으로 비교하세요.'),
    (14, 4, 'MULTIPLE_CHOICE', 'MEDIUM', '다음 상황에 가장 적합한 패턴을 고르시오. 애플리케이션이 Windows 테마와 macOS 테마를 지원해야 하며, 각 테마마다 버튼·체크박스·스크롤바가 서로 일관된 모양과 동작을 가져야 한다.', NULL, '테마를 바꿀 때 위젯 하나의 생성만 바꾸면 되는지, 서로 호환되는 여러 위젯 구성을 함께 교체해야 하는지 먼저 판단하세요.'),
    (14, 5, 'KEYWORD_BLANK', 'HARD', '팩토리 메서드는 생성할 객체의 실제 타입 결정을 서브클래스에 맡기는 반면, 추상 팩토리는 서로 관련된 여러 객체를 하나의 ___ 단위로 생성하는 데 초점을 둔다.', NULL, '여러 관련 제품의 호환성을 한꺼번에 유지해야 할 때 사용하는 생성 단위를 떠올려 보세요.');
