-- #193: 풀이 중 즉시 조회하는 안전한 한 문장 힌트.
-- 원본: /tmp/thumbsup-193-hints.json
-- SHA-256: 2e33d4f17b853838a54680a0f766178ea7b02fe2fdc5339697ed5746afb603fe
--
-- 운영에서 추가되거나 원문이 수정된 문제 및 승인된 IMPROVE 문제는 보존한다.
-- canonical 좌표·유형·난이도·원문이 모두 정확히 일치하는 행만 백필하고,
-- 나머지는 NULL로 남겨 API가 409로 방어한다.
CREATE TEMPORARY TABLE expected_quiz_hint (
    step_order               INT         NOT NULL,
    slot_order               INT         NOT NULL,
    quiz_type                VARCHAR(20) NOT NULL,
    difficulty               VARCHAR(10) NOT NULL,
    question_text            TEXT        NOT NULL,
    replacement_question_text TEXT       NULL,
    hint                     TEXT        NOT NULL,
    PRIMARY KEY (step_order, slot_order)
) DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_unicode_ci;


ALTER TABLE quiz
    ADD COLUMN hint TEXT NULL AFTER code_snippet;

-- question_text 보정이 있는 canonical 행은 hint와 같은 UPDATE에서 원자적으로 교체한다.
UPDATE quiz AS q
INNER JOIN expected_quiz_hint AS expected
   ON q.step_order = expected.step_order
  AND q.slot_order = expected.slot_order
  AND q.type = expected.quiz_type
  AND q.difficulty = expected.difficulty
  AND BINARY q.question_text = BINARY expected.question_text
  AND NOT EXISTS (
      SELECT 1
      FROM quiz_draft AS draft
      WHERE draft.origin = 'IMPROVE'
        AND draft.status = 'APPROVED'
        AND draft.source_quiz_id = q.id
  )
SET q.hint = expected.hint,
    q.question_text = COALESCE(expected.replacement_question_text, q.question_text);

DROP TEMPORARY TABLE IF EXISTS expected_quiz_hint;
